fn days_to_next_sunday(day: &str) -> i8 {
    // Map each day abbreviation to its index, with Sunday as 0
    // SUN=0, MON=1, TUE=2, WED=3, THU=4, FRI=5, SAT=6
    let day_index = match day {
        "SUN" => 0,
        "MON" => 1,
        "TUE" => 2,
        "WED" => 3,
        "THU" => 4,
        "FRI" => 5,
        "SAT" => 6,
        _ => unreachable!("Input is guaranteed to be one of the valid day abbreviations"),
    };
    // Calculate days until next Sunday: if today is Sunday (0), return 7
    // Otherwise, 7 - day_index gives days until next Sunday
    if day_index == 0 {
        7
    } else {
        7 - day_index
    }
}